// https://patrickjaillet.github.io/BS_shadertoy
void mainImage(out vec4 coulFrag, in vec2 coordFrag){
    g_zero = min(iFrame, 0);
    vec2 res = iResolution.xy;
    vec2 uv = (coordFrag - 0.5 * res) / res.y;

    vec3 col = texelFetch(iChannel1, ivec2(coordFrag), 0).rgb;

    vec3 lueurFine = vec3(0.0);
    vec3 lueurLarge = vec3(0.0);
    const int N = 24;
    float rotation = hachage2(coordFrag + 3.7) * 6.2831853;

    for(int i = g_zero; i < N; i++){
        float fi = float(i) + 0.5;
        float r = sqrt(fi / float(N));
        float a = fi * 2.399963 + rotation;
        vec2 dir = vec2(cos(a), sin(a)) * r;
        vec3 s1 = textureLod(iChannel0, (coordFrag + dir * 0.018 * res.y) / res, 0.0).rgb;
        vec3 s2 = textureLod(iChannel0, (coordFrag + dir * 0.07 * res.y) / res, 0.0).rgb;
        lueurFine += max(s1 - 0., 0.) * (1.0 - r * 0.5);
        lueurLarge += max(s2 - 0.2, 0.) * (1.0 - r * 0.5);
    }

    col += (lueurFine * 0.5 + lueurLarge * 0.0) / float(N);

    col += vec3(1.0, 0.8, 0.55) * poussiere(uv, iTime) * 0.35 * exp(-dot(uv, uv) * 1.5);

    col = aces(col * 1.1);
    col = pow(col, vec3(1.0 / 2.2));
    col *= clamp(1.0 - dot(uv, uv) * 0.9, 0.0, 1.0);
    col += (hachage2(coordFrag + fract(iTime)) - 0.5) * 0.025;

    coulFrag = vec4(clamp(col, 0.0, 1.0), 1.0);
}

#define PI 3.14159265
#define DUREE_FLUX 14.0
#define DUREE_RETOURNEMENT 2.6
#define PERIODE 16.6
#define SOL (-1.26)
#define DISTANCE_MISE_AU_POINT 6.5

float g_temps, g_avancement, g_angle, g_retournement, g_levee, g_plan;
float g_niveauA, g_creuxA, g_niveauB, g_penteB, g_flux;
vec3 g_dirLum;
int g_zero;

mat2 rot(float a){
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

float hachage2(vec2 p){
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32);
    return fract(p.x * p.y);
}

float hachage3(vec3 p){
    p = fract(p * 0.3183099 + vec3(0.1));
    p *= 17.0;
    return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
}

float bruit3(vec3 x){
    vec3 i = floor(x), f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    return mix(
        mix(mix(hachage3(i), hachage3(i + vec3(1,0,0)), f.x),
            mix(hachage3(i + vec3(0,1,0)), hachage3(i + vec3(1,1,0)), f.x), f.y),
        mix(mix(hachage3(i + vec3(0,0,1)), hachage3(i + vec3(1,0,1)), f.x),
            mix(hachage3(i + vec3(0,1,1)), hachage3(i + vec3(1,1,1)), f.x), f.y), f.z);
}

float fbm(vec3 p){
    float a = 0.5, s = 0.0;
    for(int i = g_zero; i < 4; i++){
        s += a * bruit3(p);
        p = p * 2.03 + vec3(1.7, 9.2, 3.1);
        a *= 0.5;
    }
    return s;
}

void definirEtat(float t){
    float tc = mod(t, PERIODE);
    float f = 1.0;
    g_retournement = 0.0;
    g_angle = 0.0;
    g_levee = 0.0;
    g_plan = 0.0;
    if(tc < DUREE_FLUX){
        f = tc / DUREE_FLUX;
    } else {
        float w = (tc - DUREE_FLUX) / DUREE_RETOURNEMENT;
        float e = w * w * w * (w * (w * 6.0 - 15.0) + 10.0);
        g_retournement = 1.0;
        g_angle = PI * e;
        g_levee = 0.5 * pow(max(sin(g_angle), 0.0), 0.6);
        g_plan = mix(-0.25, -0.8, e) * cos(g_angle);
    }
    float fs = clamp(f / 0.93, 0.0, 1.0);
    g_avancement = fs;
    g_niveauB = mix(-1.05, -0.25, fs);
    g_penteB = mix(0.75, 0.0, fs * fs * fs);
    g_niveauA = mix(0.8, -0.03, fs);
    g_creuxA = 0.3 * smoothstep(0.0, 0.15, fs) * (1.0 - smoothstep(0.7, 0.96, fs));
    g_flux = (g_retournement > 0.5) ? 0.0 : smoothstep(0.004, 0.02, fs) * (1.0 - smoothstep(0.945, 0.975, fs));
}

float rayonInt(float y){
    float t = clamp(abs(y) / 1.05, 0.0, 1.0);
    return 0.05 + 0.5 * pow(sin(t * 1.5707963), 0.7);
}

vec3 versLocal(vec3 pw){
    vec3 pc = pw - vec3(0.0, g_levee, 0.0);
    return vec3(rot(g_angle) * pc.xy, pc.z);
}

float distanceSable(vec3 pc, vec3 p){
    float r = length(p.xz);
    float dint = max((r - rayonInt(p.y) + 0.006) * 0.7, abs(p.y) - 1.04);
    float rw = length(pc.xz);
    float d;
    if(g_retournement > 0.5){
        d = max(dint, pc.y - g_plan);
        d = max(d, p.y);
    } else {
        float ysA = g_niveauA + g_creuxA * (0.6 - exp(-rw * rw * 9.0));
        float ysB = g_niveauB - g_penteB * rw;
        float dA = max(max(dint, pc.y - ysA), -p.y);
        float dB = max(max(dint, pc.y - ysB), p.y);
        d = min(dA, dB);
    }
    return d;
}

float distanceVerre(vec3 pw){
    vec3 p = versLocal(pw);
    float rad = (length(p.xz) - rayonInt(p.y)) * 0.7;
    float d = abs(rad - 0.012) - 0.012;
    return max(d, abs(p.y) - 1.09);
}

vec2 carte(vec3 pw){
    vec3 pc = pw - vec3(0.0, g_levee, 0.0);
    vec3 p = vec3(rot(g_angle) * pc.xy, pc.z);
    vec2 res = vec2(pw.y - SOL, 0.0);
    float ay = abs(p.y);
    float rr = length(p.xz);

    vec2 q = vec2(rr - 0.71, abs(ay - 1.17) - 0.05);
    float dc = length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - 0.04;
    if(dc < res.x) res = vec2(dc, 1.0);

    float ang = atan(p.z, p.x) + 0.52;
    float sect = 2.0 * PI / 3.0;
    float a = mod(ang, sect) - 0.5 * sect;
    vec2 qq = rr * vec2(cos(a), sin(a));
    float dp = max(length(qq - vec2(0.655, 0.0)) - 0.032, ay - 1.14);
    if(dp < res.x) res = vec2(dp, 2.0);

    float ds = distanceSable(pc, p);
    if(ds < res.x) res = vec2(ds, 3.0);

    if(g_flux > 0.001){
        vec2 ondul = 0.004 * vec2(sin(pc.y * 40.0 - g_temps * 30.0), cos(pc.y * 33.0 - g_temps * 25.0));
        float df = length(pc.xz + ondul) - 0.011 * g_flux;
        df = max(df, max(pc.y - 0.04, g_niveauB - pc.y));
        if(df < res.x) res = vec2(df, 4.0);
    }
    return res;
}

float marche(vec3 ro, vec3 rd, float tmin, float tmax, out float m){
    float t = tmin;
    m = -1.0;
    for(int i = 0; i < 110; i++){
        vec2 h = carte(ro + rd * t);
        if(h.x < 0.0006 * t){
            m = h.y;
            return t;
        }
        t += h.x * 0.8;
        if(t > tmax) break;
    }
    return -1.0;
}

float marcheVerre(vec3 ro, vec3 rd){
    float t = 0.5;
    for(int i = 0; i < 90; i++){
        float h = distanceVerre(ro + rd * t);
        if(h < 0.0004 * t) return t;
        t += h * 0.75;
        if(t > 16.0) break;
    }
    return -1.0;
}

vec3 normale(vec3 p){
    vec3 n = vec3(0.0);
    for(int i = g_zero; i < 4; i++){
        vec3 e = 2.0 * vec3(float(((i + 3) >> 1) & 1), float((i >> 1) & 1), float(i & 1)) - 1.0;
        n += e * carte(p + e * 0.0008).x;
    }
    return normalize(n);
}

vec3 normaleVerre(vec3 p){
    vec3 n = vec3(0.0);
    for(int i = g_zero; i < 4; i++){
        vec3 e = 2.0 * vec3(float(((i + 3) >> 1) & 1), float((i >> 1) & 1), float(i & 1)) - 1.0;
        n += e * distanceVerre(p + e * 0.0006);
    }
    return normalize(n);
}

float ombreDouce(vec3 ro, vec3 rd){
    float res = 1.0, t = 0.03;
    for(int i = 0; i < 28; i++){
        float h = carte(ro + rd * t).x;
        res = min(res, 10.0 * h / t);
        t += clamp(h, 0.02, 0.25);
        if(res < 0.002 || t > 5.0) break;
    }
    res = clamp(res, 0.0, 1.0);
    return res * res * (3.0 - 2.0 * res);
}

float occlusion(vec3 p, vec3 n){
    float o = 0.0, s = 1.0;
    for(int i = g_zero; i < 5; i++){
        float h = 0.01 + 0.09 * float(i);
        o += (h - carte(p + n * h).x) * s;
        s *= 0.75;
    }
    return clamp(1.0 - 2.2 * o, 0.0, 1.0);
}

vec3 fondEnv(vec3 rd){
    vec3 c = mix(vec3(0.010, 0.009, 0.012), vec3(0.05, 0.035, 0.03), clamp(rd.y * 0.5 + 0.5, 0.0, 1.0));
    c += vec3(1.0, 0.5, 0.2) * 0.22 * pow(max(dot(rd, normalize(vec3(0.15, 0.05, -1.0))), 0.0), 5.0);
    return c;
}

vec3 environnement(vec3 rd){
    vec3 c = fondEnv(rd);
    float b1 = pow(max(dot(rd, g_dirLum), 0.0), 60.0);
    c += vec3(1.0, 0.8, 0.55) * b1 * 9.0;
    float b2 = (1.0 - smoothstep(0.05, 0.09, abs(rd.x - 0.7))) * smoothstep(-0.1, 0.1, rd.y)
             * (1.0 - smoothstep(0.55, 0.7, rd.y)) * step(0.0, rd.z);
    c += vec3(0.55, 0.7, 1.0) * b2 * 1.4;
    float b3 = pow(max(dot(rd, normalize(vec3(-0.3, 0.5, -0.9))), 0.0), 30.0);
    c += vec3(1.0, 0.9, 0.8) * b3 * 3.0;
    return c;
}

vec3 couleurSurface(vec3 pos, vec3 nor, vec3 rd, float matiere){
    vec3 pl = versLocal(pos);
    vec3 alb = vec3(0.02, 0.018, 0.02);
    float lustre = 60.0;
    float f0 = 0.04;
    float metal = 0.0;
    float transl = 0.0;
    float reflet = 0.5;
    float eclat = 0.0;
    vec3 n = nor;

    if(matiere > 0.5 && matiere < 1.5){
        float rayon = length(pl.xz);
        float veine = 0.5 + 0.5 * sin(rayon * 46.0 + 5.0 * fbm(pl * vec3(3.0, 1.5, 3.0)));
        alb = mix(vec3(0.06, 0.026, 0.011), vec3(0.22, 0.10, 0.04), veine);
        float anneau = 1.0 - smoothstep(0.004, 0.010, abs(rayon - 0.62));
        alb = mix(alb, vec3(0.95, 0.68, 0.32), anneau);
        metal = anneau;
        lustre = 140.0;
        f0 = 0.05;
        reflet = 0.35 + 0.4 * anneau;
    } else if(matiere > 1.5 && matiere < 2.5){
        alb = vec3(0.95, 0.68, 0.32) * (0.85 + 0.15 * bruit3(pos * 35.0));
        metal = 1.0;
        lustre = 220.0;
        reflet = 1.0;
    } else if(matiere > 2.5 && matiere < 3.5){
        vec3 g = vec3(bruit3(pos * 170.0), bruit3(pos * 170.0 + 7.3), bruit3(pos * 170.0 + 13.1)) - 0.5;
        n = normalize(nor + 0.45 * g);
        float c = bruit3(pos * 80.0);
        vec3 cellule = floor(pos * 240.0);
        alb = mix(vec3(0.50, 0.31, 0.13), vec3(0.95, 0.72, 0.38), clamp(c * 1.3, 0.0, 1.0))
            * (0.7 + 0.6 * hachage3(cellule));
        transl = 0.6;
        lustre = 25.0;
        reflet = 0.05;
        vec3 nn = normalize(vec3(hachage3(cellule + 1.0), hachage3(cellule + 2.0), hachage3(cellule + 3.0)) - 0.5);
        vec3 hv = normalize(g_dirLum - rd);
        eclat = pow(max(dot(nn, hv), 0.0), 260.0) * step(0.55, hachage3(cellule + 5.0)) * 9.0;
    } else if(matiere > 3.5){
        alb = vec3(1.0, 0.78, 0.42);
        transl = 1.0;
        lustre = 20.0;
        reflet = 0.0;
    }

    vec3 L = g_dirLum;
    float ombre = ombreDouce(pos + nor * 0.012, L);
    float ao = occlusion(pos, nor);
    float ndl = max(dot(n, L), 0.0);
    vec3 cle = vec3(1.0, 0.78, 0.52) * 3.4;
    vec3 dirR = normalize(vec3(0.7, 0.15, 0.7));
    vec3 remp = vec3(0.35, 0.5, 0.8) * 0.6;
    vec3 dirC = normalize(vec3(-0.3, 0.35, -0.9));
    vec3 contre = vec3(1.0, 0.85, 0.7) * 1.4;

    vec3 lumiere = cle * ndl * ombre
                 + remp * (0.5 + 0.5 * dot(n, dirR))
                 + contre * max(dot(n, dirC), 0.0)
                 + fondEnv(n) * 5.0;

    vec3 col = alb * (1.0 - metal) * lumiere * mix(1.0, ao, 0.9);
    col += transl * alb * cle * pow(clamp(dot(rd, L), 0.0, 1.0), 3.0) * (0.3 + 0.7 * ombre) * 0.9;

    vec3 hh = normalize(L - rd);
    float cv = max(dot(n, -rd), 0.0);
    vec3 f = mix(vec3(f0), alb, metal);
    vec3 fr = f + (1.0 - f) * pow(1.0 - cv, 5.0);
    float sp = pow(max(dot(n, hh), 0.0), lustre) * (lustre + 8.0) * 0.04 * ndl * ombre;
    col += cle * sp * fr;
    col += environnement(reflect(rd, n)) * fr * ao * reflet;
    col += vec3(1.0, 0.85, 0.6) * eclat * ombre;
    if(matiere > 3.5) col += alb * 1.6;
    return col;
}

float poussiere(vec2 uv, float t){
    float s = 0.0;
    for(int i = g_zero; i < 3; i++){
        float fi = float(i);
        vec2 q = uv * (6.0 + fi * 5.0) + vec2(t * 0.03 * (fi + 1.0), -t * 0.05 * (fi + 1.0)) + fi * 17.3;
        vec2 id = floor(q);
        vec2 f = fract(q) - 0.5;
        float h = hachage2(id + fi * 7.1);
        vec2 dec = (vec2(hachage2(id + 3.1), hachage2(id + 9.7)) - 0.5) * 0.6;
        float d = length(f - dec);
        float rayon = 0.02 + 0.05 * h;
        float scint = 0.5 + 0.5 * sin(t * (1.0 + h * 3.0) + h * 40.0);
        s += (1.0 - smoothstep(0.0, rayon, d)) * step(0.55, h) * scint * (0.6 / (fi + 1.0));
    }
    return s;
}

vec3 aces(vec3 x){
    return clamp((x * (2.51 * x + 0.03)) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
}

float cercleConfusion(float prof, float hauteur){
    return clamp(abs(prof - DISTANCE_MISE_AU_POINT) * 1.2 - 0.6, 0.0, 6.0) * hauteur / 720.0;
}

void mainImage(out vec4 coulFrag, in vec2 coordFrag){
    g_zero = min(iFrame, 0);
    g_temps = iTime;
    definirEtat(iTime);
    g_dirLum = normalize(vec3(-0.85, 0.75, 0.35));

    vec2 uv = (coordFrag - 0.5 * iResolution.xy) / iResolution.y;

    float az = 0.45 * sin(iTime * 0.11) + 0.25;
    float el = 0.16 + 0.05 * sin(iTime * 0.07);
    if(iMouse.z > 0.0){
        az = (iMouse.x / iResolution.x - 0.5) * 4.0;
        el = 0.02 + (iMouse.y / iResolution.y) * 0.9;
    }

    vec3 cible = vec3(0.0, 0.1, 0.0);
    vec3 ro = cible + DISTANCE_MISE_AU_POINT * vec3(sin(az) * cos(el), sin(el), cos(az) * cos(el));
    vec3 cw = normalize(cible - ro);
    vec3 cu = normalize(cross(cw, vec3(0.0, 1.0, 0.0)));
    vec3 cv = cross(cu, cw);
    vec3 rd = normalize(uv.x * cu + uv.y * cv + 2.0 * cw);

    vec3 poids = vec3(1.0);
    vec3 ajout = vec3(0.0);
    float prof = 40.0;
    int mode = 0;

    for(int it = g_zero; it < 3; it++){
        float m;
        float tg = -1.0;
        if(mode == 0) tg = marcheVerre(ro, rd);
        float tmax = (tg > 0.0) ? tg : 30.0;
        float t = marche(ro, rd, 0.02, tmax, m);

        if(t < 0.0){
            if(tg > 0.0){
                vec3 pg = ro + rd * tg;
                vec3 ng = normaleVerre(pg);
                float cs = clamp(dot(ng, -rd), 0.0, 1.0);
                float F = 0.04 + 0.96 * pow(1.0 - cs, 5.0);
                vec3 rdb = normalize(mix(rd, refract(rd, ng, 1.0 / 1.5), 0.55));
                vec3 absorption = exp(-vec3(0.30, 0.09, 0.13) * 0.5 / max(cs, 0.25));
                vec3 R = reflect(rd, ng);
                float speculaire = pow(max(dot(R, g_dirLum), 0.0), 500.0) * 40.0;
                ajout += poids * (environnement(R) * F
                                + speculaire * vec3(1.0, 0.85, 0.6)
                                + vec3(0.02, 0.05, 0.045) * pow(1.0 - cs, 3.0) * 0.8);
                poids *= absorption * (1.0 - F);
                if(it == 0) prof = tg;
                ro = pg - ng * 0.04;
                rd = rdb;
                mode = 1;
                continue;
            }
            ajout += poids * environnement(rd);
            break;
        }

        if(it == 0) prof = t;
        vec3 pos = ro + rd * t;
        vec3 nor = normale(pos);
        bool sol = (m < 0.5) && (mode != 2);
        vec3 nrm = nor;
        if(sol) nrm = normalize(nor + vec3(bruit3(pos * 14.0) - 0.5, 0.0, bruit3(pos * 14.0 + 4.0) - 0.5) * 0.05);

        vec3 c = couleurSurface(pos, nrm, rd, m);
        float k = 1.0 - exp(-t * ((mode == 2) ? 0.06 : 0.055));
        vec3 fond = fondEnv(rd);

        if(sol){
            float cosv = max(dot(nrm, -rd), 0.0);
            float F = mix(0.22, 1.0, pow(1.0 - cosv, 5.0));
            ajout += poids * ((1.0 - k) * (1.0 - F) * c + k * fond);
            poids *= (1.0 - k) * F;
            ro = pos + nrm * 0.01;
            rd = reflect(rd, nrm);
            mode = 2;
        } else {
            ajout += poids * ((1.0 - k) * c + k * fond);
            break;
        }
    }

    coulFrag = vec4(ajout, prof);
}

void mainImage(out vec4 coulFrag, in vec2 coordFrag){
    g_zero = min(iFrame, 0);
    vec2 res = iResolution.xy;
    vec4 centre = texelFetch(iChannel0, ivec2(coordFrag), 0);
    float c = cercleConfusion(centre.a, res.y);

    if(c < 0.35){
        coulFrag = centre;
        return;
    }

    vec3 somme = centre.rgb;
    float poids = 1.0;
    const int N = 32;
    float rotation = hachage2(coordFrag) * 6.2831853;

    for(int i = g_zero; i < N; i++){
        float fi = float(i) + 0.5;
        float r = sqrt(fi / float(N));
        float a = fi * 2.399963 + rotation;
        vec2 dec = vec2(cos(a), sin(a)) * r * c;
        vec4 s = textureLod(iChannel0, (coordFrag + dec) / res, 0.0);
        float cs = cercleConfusion(s.a, res.y);
        float w = clamp(cs - length(dec) + 1.0, 0.0, 1.0);
        float lum = dot(s.rgb, vec3(0.3, 0.59, 0.11));
        w *= 1.0 + 0.5 * min(lum, 8.0);
        somme += s.rgb * w;
        poids += w;
    }

    coulFrag = vec4(somme / poids, centre.a);
}
